	}

	@ConfigItem(
		keyName = ZulrahHelperPlugin.DISPLAY_SNAKELINGS_KEY,
		section = ZulrahHelperPlugin.SECTION_PHASE_OVERLAYS,
		name = "Snakeling Icons",
		description = "Display snakeling spawns",
		position = 3
