package com.zulrahhelper.tree;

import java.util.ArrayList;
import java.util.List;
import javax.annotation.Nonnull;
import lombok.Builder;
import lombok.EqualsAndHashCode;
import lombok.Getter;
import lombok.Singular;
import lombok.ToString;

@Getter
@Builder()
@EqualsAndHashCode(onlyExplicitlyIncluded = true)
@ToString(onlyExplicitlyIncluded = true)
public class Node
{
	protected Node parent;

	@ToString.Include
	@EqualsAndHashCode.Include
	protected Step value;

	@Singular
	protected List<Node> children;

	public int size()
	{
		return this.getChildren().size();
	}

	public Node find(Step val)
	{
		if (this.value.equals(val))
		{
			return this;
		}

		for (var c : children)
		{
			var n = c.find(val);
			if (n != null)
			{
				return n;
			}
		}

		return null;
	}

	public boolean find(Node node)
	{
		if (node == null)
		{
			return false;
		}

		if (this == node || this.value.equals(node.value))
		{
			return true;
		}

		for (var c : children)
		{
			if (c.find(node))
			{
				return true;
			}
		}

		return false;
	}

	public static Node of(@Nonnull Node n)
	{
		return new Node(null, n.value, new ArrayList<>());
	}

	public static class NodeBuilder
	{
		NodeBuilder parentBuilder;

		public NodeBuilder node()
		{
			var c = Node.builder();
			c.parentBuilder = this;
			return c;
		}

		public Node buildUp()
		{
			NodeBuilder b = this;
			NodeBuilder p;
			Node n = null;
			while (b != null)
			{
				n = b.build();
				p = b.parentBuilder;
				if (p != null)
				{
					p.child(n);
				}
				b = p;
			}

			return n;
		}

		public Node build()
		{
			if (this.children == null)
			{
				this.children = new ArrayList<>();
			}

			Node n = new Node(null, this.value, this.children);

			for (var c : n.children)
			{
				c.parent = n;
			}

			return n;
		}
	}
}

